import { safeLog } from "@/lib/observability";
import "server-only";

import { db } from "@/lib/db";
import { billingConfig } from "@/lib/billing/config";

import {
  processBillingEvent,
  reconcileBillingSubscription,
} from "@/lib/billing/lifecycle";
import { recoverCheckoutAttempt } from "@/lib/billing/checkout";
import { openCheckoutStates } from "@/lib/billing/store";
import { recoverBillingCancellation } from "./cancel";

// The committed inbox is the source of pending work. If post-response processing
// is interrupted, scheduled recovery retries the receipt using its durable backoff.
export async function retryBillingInbox() {
  try {
    billingConfig();
  } catch {
    return { disabled: true };
  }
  const rows = await db.billingWebhookEvent.findMany({
    where: {
      processedAt: null,
      state: { in: ["RECEIVED", "RETRY"] },
      OR: [{ nextAttemptAt: null }, { nextAttemptAt: { lte: new Date() } }],
    },
    orderBy: [{ receivedAt: "asc" }, { id: "asc" }],
    take: 100,
  });
  let processed = 0;
  for (const row of rows) {
    try {
      await processBillingEvent(row.id);
      processed++;
    } catch {
      /* durable nextAttemptAt */
    }
  }
  return { processed, pending: rows.length - processed };
}

// Provider callbacks normally update access immediately; scheduled recovery repairs
// interrupted processing and missed delivery.
export async function recoverBilling() {
  try {
    billingConfig();
  } catch {
    return { disabled: true };
  }
  const inbox = await retryBillingInbox();
  const attempts = await db.checkoutAttempt.findMany({
    where: {
      userId: { not: null },
      status: { in: openCheckoutStates },
      updatedAt: { lte: new Date(Date.now() - 30_000) },
    },
    orderBy: [{ updatedAt: "asc" }, { id: "asc" }],
    take: 50,
    select: { id: true, userId: true },
  });
  let checkoutFailures = 0;
  for (const attempt of attempts) {
    try {
      await recoverCheckoutAttempt(attempt.userId!, attempt.id);
      await db.checkoutAttempt.updateMany({
        where: {
          id: attempt.id,
          userId: attempt.userId,
          status: { in: openCheckoutStates },
        },
        data: { updatedAt: new Date() },
      });
    } catch {
      checkoutFailures++;
      // Rotate failures so one uncertain owner cannot starve the rest.
      await db.checkoutAttempt.updateMany({
        where: { id: attempt.id, userId: attempt.userId },
        data: { updatedAt: new Date() },
      });
    }
  }
  // Include mid-period cancellation/failure and recovery from hold, even if a
  // provider webhook was missed. Rotate through all attached nonterminal rows.
  const subscriptions = await db.billingSubscription.findMany({
    where: {
      userId: { not: null },
      OR: [
        { status: { notIn: ["CANCELLED", "EXPIRED", "FAILED"] } },
        { status: "CANCELLED", cancelAtPeriodEnd: true },
        { cancelRequestedAt: { not: null } },
      ],
    },
    orderBy: [{ updatedAt: "asc" }, { id: "asc" }],
    take: 50,
    select: { userId: true, dodoSubscriptionId: true },
  });
  let failed = 0;
  for (const subscription of subscriptions) {
    try {
      await recoverBillingCancellation(
        subscription.userId!,
        subscription.dodoSubscriptionId,
      );
      await reconcileBillingSubscription(
        subscription.userId!,
        subscription.dodoSubscriptionId,
      );
    } catch {
      failed++;
      // A permanently failing row must not starve other owners in the sweep.
      await db.billingSubscription.updateMany({
        where: {
          userId: subscription.userId,
          dodoSubscriptionId: subscription.dodoSubscriptionId,
        },
        data: { updatedAt: new Date() },
      });
    }
  }
  await db.billingRateLimit.deleteMany({
    where: { minuteBucket: { lt: new Date(Date.now() - 86400_000) } },
  });
  return {
    inbox,
    subscriptions: subscriptions.length,
    failed,
    checkoutFailures,
  };
}

// Pages are bounded. Owner locks and billingStateVersion fence reconciliation
// against callbacks and recovery; rerunning an interrupted command is safe.
export async function reconcileBillingPage(
  afterId: string | null,
  cutoff: string,
) {
  const rows = await db.billingSubscription.findMany({
    where: {
      userId: { not: null },
      createdAt: { lte: new Date(cutoff) },
      OR: [
        { status: { notIn: ["CANCELLED", "EXPIRED", "FAILED"] } },
        { status: "CANCELLED", cancelAtPeriodEnd: true },
        { cancelRequestedAt: { not: null } },
      ],
      ...(afterId ? { id: { gt: afterId } } : {}),
    },
    orderBy: { id: "asc" },
    take: 50,
    select: { id: true, userId: true, dodoSubscriptionId: true },
  });
  let failed = 0,
    missingSettlement = 0;
  for (const row of rows) {
    try {
      await recoverBillingCancellation(row.userId!, row.dodoSubscriptionId);
      await reconcileBillingSubscription(row.userId!, row.dodoSubscriptionId);
      const current = await db.billingSubscription.findFirst({
        where: { userId: row.userId, id: row.id },
      });
      if (
        current &&
        ["ACTIVE", "PAST_DUE"].includes(current.status) &&
        (!current.settledPaymentId ||
          !current.periodEnd ||
          current.periodEnd <= new Date())
      )
        missingSettlement++;
    } catch {
      failed++;
      safeLog("error", "billing", {
        subscriptionRecordId: row.id,
        code: "BILLING_RECONCILIATION_FAILED",
      });
    }
  }
  return {
    cursor: rows.length === 50 ? rows.at(-1)!.id : null,
    scanned: rows.length,
    failed,
    missingSettlement,
  };
}

async function reconcileCheckoutPage(afterId: string | null, cutoff: string) {
  const rows = await db.checkoutAttempt.findMany({
    where: {
      userId: { not: null },
      status: { in: openCheckoutStates },
      createdAt: { lte: new Date(cutoff) },
      ...(afterId ? { id: { gt: afterId } } : {}),
    },
    orderBy: { id: "asc" },
    take: 50,
    select: { id: true, userId: true },
  });
  let failed = 0;
  for (const row of rows) {
    try {
      await recoverCheckoutAttempt(row.userId!, row.id);
    } catch {
      failed++;
    }
  }
  return {
    cursor: rows.length === 50 ? rows.at(-1)!.id : null,
    scanned: rows.length,
    failed,
  };
}

export async function reconcileBilling() {
  try {
    billingConfig();
  } catch {
    return { disabled: true };
  }
  const cutoff = new Date().toISOString();
  let cursor: string | null = null;
  const totals = { scanned: 0, failed: 0, missingSettlement: 0 };
  do {
    const result = await reconcileBillingPage(cursor, cutoff);
    totals.scanned += result.scanned;
    totals.failed += result.failed;
    totals.missingSettlement += result.missingSettlement;
    cursor = result.cursor;
  } while (cursor);
  do {
    const result = await reconcileCheckoutPage(cursor, cutoff);
    totals.failed += result.failed;
    cursor = result.cursor;
  } while (cursor);
  const recovery = await recoverBilling();
  if (!("disabled" in recovery))
    totals.failed +=
      recovery.failed +
      recovery.checkoutFailures +
      (recovery.inbox && "pending" in recovery.inbox
        ? (recovery.inbox.pending ?? 0)
        : 0);
  const [quarantined, staleInbox, conflictingSubscriptions] = await Promise.all(
    [
      db.billingWebhookEvent.count({ where: { state: "QUARANTINED" } }),
      db.billingWebhookEvent.count({
        where: {
          processedAt: null,
          state: { in: ["RECEIVED", "RETRY"] },
          receivedAt: { lt: new Date(Date.now() - 3600_000) },
        },
      }),
      db.billingWebhookEvent.count({
        where: { failureCode: "CONFLICTING_SUBSCRIPTIONS" },
      }),
    ],
  );
  safeLog("info", "nightly", {
    ...totals,
    quarantined,
    staleInbox,
    conflictingSubscriptions,
    complete: totals.failed === 0,
  });
  if (totals.failed) throw new Error("BILLING_NIGHTLY_INCOMPLETE");
  return totals;
}
